// ── Apply threshold and cap (mirrors analyzeChord's filter) ─────────────
//
// threshold = (bestScore - winnerAppliedBassBonus) * kScoreThresholdRatio
// Sort candidates by re-scored value, keep top-3.
// (We only affect which candidate is promoted to position 0; the detailed
//  re-sort of all candidates is deferred to E2d.)

if (winnerIdx < 0) {
    // Edge case: winner was filtered out by the suppressed-signal threshold
    // (this can happen if the true winner's suppressed score is below the
    // suppressed-signal threshold, i.e. a different bass won the suppressed
    // pass). Do NOT crash; keep the suppressed-signal winner as-is.
    // This case is expected to be absent from the current test corpus.
    return;
}

// ── Step 2: Pass B simulation ────────────────────────────────────────────
//
// Replicates applyStepBonusGuard() per bass group, for BOTH score variants
// independently.  Cells within each bass group are in (rootPc, tplIdx)
// row-major order — same iteration order as the original lambda.
//
// Gate: jointScoringEnabled (same as original).
// Bonus: kWStepIn (step-in from prev bass), kWStepOut (step-out to next).
// Root-position only; Power excluded.
// m7-family guard (compRootPc = (bassPc-3+12)%12): blocked when any other
// cell in the same bass group has rootPc==compRootPc, quality in
// {Dim, HalfDim, Minor+4-intervals}, and score >= cand_score - kStepBudget.
// Guard comparison uses the LIVE score (modified in-place by earlier
// iterations) — matches the original lambda's in-place behaviour.

for (auto& [sc, idx] : bassEntries) {
    const auto& id = candidates[idx].identity;
    using Q = analysis::ChordQuality;
    // Root-position only; Power excluded.
    if (id.rootPc == id.bassPc && id.quality != Q::Power) {
        // m7-family guard: for Minor chords with 4 intervals (Min7),
        // the step bonus may not push score above kStepBudget above the
        // un-bonused score.  Find the cell to get intervalCount.
        bool isMin7 = false;
        for (const auto& cell : winningCells) {
            if (cell.bassPc      == id.bassPc
                && cell.rootPc   == id.rootPc
                && cell.tiePriority == id.tiePriority) {
                isMin7 = (cell.quality == Q::Minor && cell.intervalCount == 4);
                break;
            }
        }
        double bonus = 0.0;
        if (stepIn  && (!isMin7 || sc + kWStepIn  <= winnerScore + kStepBudget))
            bonus += kWStepIn;
        if (stepOut && (!isMin7 || sc + kWStepOut <= winnerScore + kStepBudget))
            bonus += kWStepOut;
        sc += bonus;
    }
}

